from datetime import datetime
from airflow.decorators import dag, task
from airflow.datasets import Dataset  # Asset in Airflow 3.x

orders_clean = Dataset("s3://warehouse/analytics/orders_daily")

# Producer: time-scheduled, and it UPDATES the dataset on success.
@dag(
    dag_id="orders_producer",
    start_date=datetime(2026, 1, 1),
    schedule="0 6 * * *",
    catchup=False,
)
def orders_producer():
    @task(outlets=[orders_clean])   # marks the dataset updated when this succeeds
    def build_orders(**context):
        ds = context["ds"]
        # ... write partition for `ds` ...
        return ds
    build_orders()

orders_producer()

# Consumer: NO cron. It runs automatically whenever orders_clean is updated.
@dag(
    dag_id="orders_report",
    start_date=datetime(2026, 1, 1),
    schedule=[orders_clean],        # data-aware / asset-based scheduling
    catchup=False,
)
def orders_report():
    @task
    def refresh_dashboard(**context):
        # runs right after the producer updates the dataset
        print("Refreshing for interval", context["data_interval_start"])
    refresh_dashboard()

orders_report()
